<script setup lang="ts">
import { computed } from 'vue'
import { memorySegments, type MemorySegment } from '../lib/widget-data'
const props = withDefaults(defineProps<{ rangeStart?: number; rangeSize?: number; segments?: MemorySegment[]; locale?: string }>(), { rangeStart: 0, rangeSize: 1048576, segments: () => [] })
const segments = computed(() => memorySegments(props.rangeStart, props.rangeSize, Array.isArray(props.segments) ? props.segments : []))
const en = computed(() => props.locale?.startsWith('en'))
function hex(value: number) { return Number.isSafeInteger(value) ? `0x${value.toString(16).toUpperCase().padStart(8,'0')}` : '—' }
</script>
<template><figure class="memory-map-view"><div class="memory-map-axis"><span>{{ hex(rangeStart) }}</span><span>{{ hex(rangeStart + rangeSize) }}</span></div><div class="memory-map-lanes" :aria-label="en ? 'Memory map, half-open intervals' : '内存分布，左闭右开区间'"><div v-for="segment in segments" :key="segment.id" class="memory-map-lane"><span v-if="segment.fraction > 0" class="memory-map-block" :class="{overlap:segment.overlap}" :style="{left:`${segment.offset*100}%`,width:`${segment.fraction*100}%`,backgroundColor:segment.overlap?'#c50f1f':segment.color||'#0f6cbd'}" :title="`${segment.label || segment.id}: [${hex(segment.start)}, ${hex(segment.start+segment.size)})`"/></div></div><ul><li v-for="segment in segments" :key="segment.id" :class="{invalid:!segment.valid||segment.overlap||segment.outOfRange}"><span class="memory-map-swatch" :style="{backgroundColor:segment.overlap?'#c50f1f':segment.color||'#0f6cbd'}"/><span>{{segment.label || segment.id}}</span><code>[{{hex(segment.start)}}, {{hex(segment.start+segment.size)}})</code><strong v-if="!segment.valid">{{en?'Invalid range':'区间无效'}}</strong><strong v-else-if="segment.overlap">{{en?'Overlap':'重叠'}}</strong><strong v-if="segment.outOfRange">{{en?'Out of range':'超出范围'}}</strong></li></ul><small v-if="!segments.length">{{en?'No enabled segments':'没有启用的分段'}}</small></figure></template>
<style scoped>.memory-map-view{margin:0;display:flex;flex-direction:column;gap:8px;overflow:auto;min-height:0}.memory-map-axis{display:flex;justify-content:space-between;font:11px Consolas,monospace}.memory-map-lanes{border:1px solid #b7c1cd;background:#f3f6fa;padding:3px 0;min-height:24px}.memory-map-lane{position:relative;height:13px;margin:2px 0}.memory-map-block{position:absolute;height:100%;min-width:3px;border-radius:2px}.memory-map-view ul{margin:0;padding:0;list-style:none;font-size:11px}.memory-map-view li{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:2px 0}.memory-map-swatch{width:8px;height:8px;flex-shrink:0}.memory-map-view strong{font-weight:500}.memory-map-view .invalid{color:#b10e1e}</style>
